using System;using System.IO;using System.Linq;using Newtonsoft.Json.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEditor.Build.Reporting;
[InitializeOnLoad] public static class ConRoiR38 {
 public const string Scene="Assets/Scenes/JourneyRepair_v48_r38.unity",Out="Docs/Reviews/journey_v48/r38",Art="Assets/Art/Gameplay/LakeR37";
 static ConRoiR38(){EditorApplication.playModeStateChanged+=Mode;}
 static void Mode(PlayModeStateChange p){if(p==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("r38.review",false)){SessionState.SetBool("r38.review",false);new GameObject("R38_OptInReview").AddComponent<R38LakeReview>().output=Out+"/"+SessionState.GetString("r38.output","editor-main");}}
 public static void Author(){if(File.Exists(Scene))throw new Exception("Keep derivative");AssetDatabase.CopyAsset(ConRoiR37.Scene,Scene);EditorSceneManager.OpenScene(Scene);EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene(Scene,true)};EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);EditorSceneManager.OpenScene(Scene);Validate();}
 public static void Diagnose(){EditorSceneManager.OpenScene(Scene);SessionState.SetBool("r38.review",true);SessionState.SetString("r38.output","editor-before");EditorApplication.EnterPlaymode();}
 public static void Begin(){EditorSceneManager.OpenScene(Scene);SessionState.SetBool("r38.review",true);SessionState.SetString("r38.output","editor-main");EditorApplication.EnterPlaymode();}
 static JArray V(Vector3 v)=>new JArray(v.x,v.y,v.z);static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
 public static void Validate(){
  var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var a=UnityEngine.Object.FindAnyObjectByType<TuongTacSoTayHoR37>();var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();
  var missing=new JArray(all.Where(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0).Select(t=>P(t)));var required=new JArray();Action<string,UnityEngine.Object> need=(n,o)=>required.Add(new JObject{["field"]=n,["valid"]=o!=null,["target"]=o?o.name:"NULL"});
  need("story",a.story);need("root",a.root);need("book",a.book);need("leaf",a.leaf);need("leftPage",a.leftPage);need("socket",a.socket);need("gesture",a.gesture);need("plan",a.planText);need("blank",a.blankText);need("cover",a.coverText);need("preview",a.preview);need("collider",a.bookCollider);need("paperSound",a.paperSound);need("closeSound",a.closeSound);need("placeSound",a.placeSound);
  var prefabs=new JArray(all.Where(t=>PrefabUtility.IsAnyPrefabInstanceRoot(t.gameObject)).Select(t=>new JObject{["path"]=P(t),["source"]=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject),["status"]=PrefabUtility.GetPrefabInstanceStatus(t.gameObject).ToString()}));
  var meshes=new JArray();var geo=JObject.Parse(File.ReadAllText(Art+"/Props.geometry.json"));foreach(var row in geo["objects"]){string n=(string)row["name"];var m=AssetDatabase.LoadAssetAtPath<Mesh>(Art+"/"+n+".asset");bool same=m.vertexCount==row["vertices"].Count()&&m.triangles.SequenceEqual(row["triangles"].Select(x=>(int)x));for(int i=0;i<m.vertexCount&&same;i++){var p=row["vertices"][i];same&=Vector3.Distance(m.vertices[i],new Vector3((float)p[0],(float)p[1],(float)p[2]))<.000001f;}meshes.Add(new JObject{["mesh"]=n,["matchesBlender"]=same,["uv"]=m.uv.Length==m.vertexCount,["normals"]=m.normals.Length==m.vertexCount});}
  var j=new JObject{["scene"]=scene.path,["missingScripts"]=missing,["required"]=required,["prefabs"]=prefabs,["meshes"]=meshes,["players"]=all.Count(t=>t.GetComponent<DieuKhienDiChuyen>()),["cameras"]=all.Count(t=>t.GetComponent<Camera>()),["listeners"]=all.Count(t=>t.GetComponent<AudioListener>()),["eventSystems"]=all.Count(t=>t.GetComponent<UnityEngine.EventSystems.EventSystem>()),["serializedHarnesses"]=new JArray(all.SelectMany(t=>t.GetComponents<MonoBehaviour>()).Where(c=>c&&c.GetType().Name.Contains("Review")).Select(c=>c.GetType().Name)),["colliders"]=new JArray(a.root.GetComponentsInChildren<BoxCollider>(true).Select(c=>new JObject{["path"]=P(c.transform),["size"]=V(c.size),["scale"]=V(c.transform.lossyScale),["trigger"]=c.isTrigger,["layer"]=c.gameObject.layer,["rigidbody"]=c.attachedRigidbody!=null}))};File.WriteAllText(Out+"/source-reopened.json",j.ToString());
  if(missing.Count>0||required.Any(x=>!(bool)x["valid"])||meshes.Any(x=>!(bool)x["matchesBlender"])||prefabs.Any(x=>(string)x["status"]=="MissingAsset"))throw new Exception("r38 source audit failed");
 }
 public static void Build(){EditorSceneManager.OpenScene(Scene);Validate();EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene(Scene,true)};string exe=Path.GetFullPath("Builds/Windows_v48_r38_integrated/ConRoi.exe");Directory.CreateDirectory(Path.GetDirectoryName(exe));var r=BuildPipeline.BuildPlayer(new[]{Scene},exe,BuildTarget.StandaloneWindows64,BuildOptions.Development|BuildOptions.DetailedBuildReport);File.WriteAllText(Out+"/build.json",new JObject{["result"]=r.summary.result.ToString(),["errors"]=r.summary.totalErrors,["warnings"]=r.summary.totalWarnings,["scene"]=Scene,["binary"]=exe}.ToString());if(r.summary.result!=BuildResult.Succeeded)throw new Exception("Build failed");}

 public static void Configure(){
  EditorSceneManager.OpenScene(Scene);var a=UnityEngine.Object.FindAnyObjectByType<TuongTacSoTayHoR37>();a.pairedPagesR38=true;
  var r=a.story.GetComponent<PhanChieuMatHo>();r.urpCaptureR38=true;r.notebook=a;
  EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);EditorSceneManager.OpenScene(Scene);Validate();
  File.WriteAllText(Out+"/r38-config-reopened.json",new JObject{["pairedPages"]=UnityEngine.Object.FindAnyObjectByType<TuongTacSoTayHoR37>().pairedPagesR38,["urpCapture"]=UnityEngine.Object.FindAnyObjectByType<PhanChieuMatHo>().urpCaptureR38,["notebookReference"]=UnityEngine.Object.FindAnyObjectByType<PhanChieuMatHo>().notebook!=null}.ToString());
 }
 public static void ConfigureAndReview(){Configure();Begin();}
 public static void ShoeAndReview(){
  EditorSceneManager.OpenScene(Scene);var b=UnityEngine.Object.FindAnyObjectByType<TuTheBaoBenCauV48>();
  var g=JObject.Parse(File.ReadAllText("Assets/Art/Gameplay/LakeR38/Shoe.geometry.json"));string path="Assets/Art/Gameplay/LakeR38/Bao_Flat_Shoe_R38.asset";
  var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(!mesh){mesh=new Mesh{name="Bao_Flat_Shoe_R38"};AssetDatabase.CreateAsset(mesh,path);}else mesh.Clear();
  mesh.vertices=g["vertices"].Select(x=>new Vector3((float)x[0],(float)x[1],(float)x[2])).ToArray();mesh.triangles=g["triangles"].Select(x=>(int)x).ToArray();mesh.normals=g["normals"].Select(x=>new Vector3((float)x[0],(float)x[1],(float)x[2])).ToArray();mesh.uv=g["uv"].Select(x=>new Vector2((float)x[0],(float)x[1])).ToArray();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);
  var shoes=b.actor.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.name.Contains("Worn_Leather_Shoe")&&f.GetComponent<Renderer>().enabled).ToArray();if(shoes.Length!=2)throw new Exception("Expected Bao two displayed shoes");var rows=new JArray();
  foreach(var f in shoes){var t=f.transform;var old=new JObject{["mesh"]=f.sharedMesh.name,["position"]=V(t.position),["scale"]=V(t.lossyScale),["boundsMin"]=V(f.GetComponent<Renderer>().bounds.min),["boundsMax"]=V(f.GetComponent<Renderer>().bounds.max)};var cols=f.GetComponents<Collider>();if(cols.Length>0)throw new Exception("Inspect existing shoe collider before replacement");
   f.sharedMesh=mesh;var s=t.parent.lossyScale;t.localScale=new Vector3(1/s.x,1/s.y,1/s.z);PrefabUtility.RecordPrefabInstancePropertyModifications(t);PrefabUtility.RecordPrefabInstancePropertyModifications(f);
   rows.Add(new JObject{["path"]=P(t),["before"]=old,["afterMesh"]=f.sharedMesh.name,["afterPosition"]=V(t.position),["afterScale"]=V(t.lossyScale),["afterBoundsMin"]=V(f.GetComponent<Renderer>().bounds.min),["afterBoundsMax"]=V(f.GetComponent<Renderer>().bounds.max),["colliders"]=cols.Length,["material"]=f.GetComponent<Renderer>().sharedMaterial.name,["matrix"]=new JArray(Enumerable.Range(0,16).Select(i=>t.localToWorldMatrix[i]))});
  }
  File.WriteAllText(Out+"/shoe-configuration.json",rows.ToString());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);EditorSceneManager.OpenScene(Scene);Validate();
  SessionState.SetBool("r38.review",true);SessionState.SetString("r38.output","editor-final");EditorApplication.EnterPlaymode();
 }
}
